WITH remaining_keys AS (SELECT channel FROM orders EXCEPT DISTINCT SELECT channel FROM orders WHERE channel = 'web'), verified AS (SELECT s.* FROM orders s JOIN remaining_keys k ON s.channel = k.channel) SELECT s.id, s.customer_id, s.order_date, s.status, s.amount, s.shipping_fee, CASE WHEN status RLIKE '^(CANCELLED|COMPLETED)$' THEN 'GROUP_A' WHEN status RLIKE '^(PENDING|SHIPPED)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS status_zone, (SELECT MAX(x.monthly_fee) FROM subscriptions x WHERE x.customer_id = s.customer_id) AS max_subscription_monthly_fee FROM verified s;
